public class OgBookmarkProvider : INotionBookmarkProvider
{
    private readonly HttpClient _http;

    public OgBookmarkProvider(HttpClient http) => _http = http;

    public async Task<IBookmarkBlockContent> ResolveBookmarkAsync(string url)
    {
        // Call your backend proxy that fetches OG tags
        var result = await _http.GetFromJsonAsync<BookmarkDto>($"/api/og?url={Uri.EscapeDataString(url)}");
        return new BookmarkBlockContent
        {
            Url         = url,
            Title       = result?.Title,
            Description = result?.Description,
            ImageUrl    = result?.Image,
            FaviconUrl  = result?.Favicon
        };
    }
}
